#include <string.h>
#include "k16/debug.h"
void k16_debug_io_snapshot(const k16_machine_t*m,k16_debug_io_t*s){unsigned n;memset(s,0,sizeof(*s));s->ticks=m->ticks;s->raster_x=m->vpu.x;s->raster_y=m->vpu.y;s->frame=m->vpu.frame;s->irq_pending=m->irq.pending;s->irq_enable=m->irq.enable;s->key_count=m->input.count;for(n=0;n<2;n++){s->joy[n]=m->input.joy[n];s->mouse_x[n]=m->input.mx[n];s->mouse_y[n]=m->input.my[n];s->mouse_buttons[n]=m->input.buttons[n];}s->uart_rx_count=m->uart.rx_count;s->uart_tx_count=m->uart.tx_count;s->uart_baud_divisor=m->uart.baud_divisor;s->eth_rx_ready=m->ethernet.rx_ready;s->eth_dma_active=m->ethernet.dma_active;s->eth_dma_tx=m->ethernet.dma_tx;s->eth_rx_len=m->ethernet.rx_len;s->eth_tx_len=m->ethernet.tx_len;s->eth_dma_pos=m->ethernet.dma_pos;s->eth_dma_len=m->ethernet.dma_len;s->eth_rx_addr=m->ethernet.rx_addr;s->eth_tx_addr=m->ethernet.tx_addr;s->dma_owner=m->dma.owner;for(n=0;n<7;n++)s->dma_slots[n]=m->dma.slots[n];}
